{"command": "python3 -c "
import datetime
for d in range(14,25):
    dt=datetime.date(2026,10,d)
    print(dt.isoformat(), dt.strftime('%a'))
""}

{"command": "cd /workspace; for t in T-01 T-02 T-03 T-04 T-05 T-06 T-07 T-08; do python3 tools/cde_calc.py $t --json; done | tee /tmp/final_runs.jsonl; echo; echo "=== log tail (worksheet of record per target = LAST run) ==="; python3 - <<'EOF'
import json
from pathlib import Path
recs={}
for line in Path('/workspace/out/cde_runs.jsonl').read_text().splitlines():
    r=json.loads(line); recs[r['target_id']]=r
for tid in sorted(recs):
    r=recs[tid]
    print(f"{tid} L{r['cde_level']} occ={r['occupancy_basis']} wc={r['weapon_class']}/{r['fuze']} est={r['nc_casualty_estimate']} ncv={r['ncv']} nsl={len(r['nsl_within_cer'])} auth={r['approval_authority']}")
EOF"}

